import {
  type ReactNode,
  useRef,
  useEffect,
  useState,
  Children,
  cloneElement,
  isValidElement,
} from 'react';

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

export type MarqueeProps = {
  speed?: number;
  reverse?: boolean;
  pauseOnHover?: boolean;
  fade?: boolean;
  draggable?: boolean;
  duration?: number;
  multiplier?: number;
  sensitivity?: number;
  /** Solo en draggable: false deja la tira quieta hasta que la arrastren. */
  autoplay?: boolean;
  /** Solo en draggable: arrastre-retardo de los items. 0 = sin retardo. */
  lag?: number;
  /** Solo en draggable sin autoplay: imanta a limite de item al soltar. */
  snap?: 'true' | 'auto' | 'false';
  /** Solo en draggable: flechas prev/next a los costados. */
  controls?: boolean;
  /** Etiquetas accesibles de las flechas. El DS no las inyecta: este sitio
      corre en tres idiomas y una etiqueta fija seria incorrecta en dos. */
  prevLabel?: string;
  nextLabel?: string;
  children: ReactNode;
  className?: string;
};

export function Marquee({
  speed = 75,
  reverse = false,
  pauseOnHover = false,
  fade = true,
  draggable = false,
  duration: draggableDuration = 20,
  multiplier = 35,
  sensitivity = 0.01,
  autoplay = true,
  lag = 0,
  snap = 'false',
  controls = false,
  prevLabel = 'Previous',
  nextLabel = 'Next',
  children,
  className,
}: MarqueeProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const [cssDuration, setCssDuration] = useState('30s');

  // CSS mode: calculate duration based on content width
  useEffect(() => {
    if (draggable || !listRef.current) return;
    const width = listRef.current.offsetWidth;
    setCssDuration(`${width / speed}s`);
  }, [speed, children, draggable]);

  // CSS mode: IntersectionObserver pause
  useEffect(() => {
    if (draggable || !containerRef.current) return;
    const el = containerRef.current;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          el.style.setProperty('--marquee-state', entry.isIntersecting ? 'running' : 'paused');
        });
      },
      { threshold: 0 },
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [draggable]);

  const listContent = Children.toArray(children);

  // Draggable mode: GSAP animation via data-attribute contract.
  // marquee--draggable no es decorativo: apaga la animacion CSS de __list. En
  // este modo el desplazamiento lo pone GSAP sobre __collection, y con las dos
  // vivas la tira avanza al doble sobre el mismo eje.
  if (draggable) {
    return (
      <>
      <div
        ref={containerRef}
        data-draggable-marquee=""
        data-direction={reverse ? 'right' : 'left'}
        data-duration={draggableDuration}
        data-multiplier={multiplier}
        data-sensitivity={sensitivity}
        data-autoplay={autoplay ? 'true' : 'false'}
        data-lag={lag}
        data-snap={snap}
        className={cn('marquee', 'marquee--draggable', fade && 'marquee--fade', className)}
      >
        <div data-draggable-marquee-collection="" className="marquee__collection">
          <div data-draggable-marquee-list="" className="marquee__list">
            {listContent}
          </div>
        </div>
      </div>
      {controls && (
        <div className="marquee__controls">
          <button
            type="button"
            className="marquee__control marquee__control--prev"
            data-draggable-marquee-control="prev"
            aria-label={prevLabel}
          />
          <button
            type="button"
            className="marquee__control marquee__control--next"
            data-draggable-marquee-control="next"
            aria-label={nextLabel}
          />
        </div>
      )}
      </>
    );
  }

  // CSS mode
  return (
    <div
      ref={containerRef}
      className={cn(
        'marquee',
        reverse && 'marquee--reverse',
        pauseOnHover && 'marquee--pause-hover',
        fade && 'marquee--fade',
        className,
      )}
      style={{ '--marquee-duration': cssDuration } as React.CSSProperties}
    >
      <div ref={listRef} className="marquee__list">
        {listContent}
      </div>
      <div className="marquee__list" aria-hidden="true">
        {listContent}
      </div>
    </div>
  );
}

/* ---- Item ---- */

export function MarqueeItem({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={cn('marquee__item', className)}>{children}</div>;
}

/* ---- Separator ---- */

export function MarqueeSeparator({ children, className }: { children?: ReactNode; className?: string }) {
  const defaultStar = (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 50 50" fill="currentColor">
      <path d="M17.6777 32.3223C12.9893 27.6339 6.63041 25 0 25C6.63041 25 12.9893 22.3661 17.6777 17.6777C22.3661 12.9893 25 6.63041 25 0C25 6.63041 27.6339 12.9893 32.3223 17.6777C37.0107 22.3661 43.3696 25 50 25C43.3696 25 37.0107 27.6339 32.3223 32.3223C27.6339 37.0107 25 43.3696 25 50C25 43.3696 22.3661 37.0107 17.6777 32.3223Z" />
    </svg>
  );

  return (
    <span className={cn('marquee__separator', className)}>
      {children || defaultStar}
    </span>
  );
}

/* -------------------------------------------------------------------------
   Marquee

   Infinite horizontal scroll. CSS animation, JS for speed + duplication.
   Pauses when out of viewport. Hover pauses optional.

   Parts: .marquee, .marquee__list, .marquee__item
   ------------------------------------------------------------------------- */

/* ---- Container ---- */

.marquee {
  display: flex;
  position: relative;
  overflow: hidden;
  width: 100%;
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
}

/* ---- Fade edges ---- */

.marquee--fade {
  mask-image: linear-gradient(
    to right,
    transparent,
    black var(--spacing-10, 40px),
    black calc(100% - var(--spacing-10, 40px)),
    transparent
  );
  -webkit-mask-image: linear-gradient(
    to right,
    transparent,
    black var(--spacing-10, 40px),
    black calc(100% - var(--spacing-10, 40px)),
    transparent
  );
}

/* ---- List (duplicated by JS) ---- */

/* stretch y no center: los items miden lo mismo que el mas alto de la fila, y
   cada uno decide dentro como coloca su contenido (.marquee__item sigue
   centrando el suyo, asi que una tira de logos no cambia). Es lo que permite
   que una fila de cards se lea pareja aunque una lleve mas texto. */
.marquee__list {
  flex: none;
  display: flex;
  align-items: stretch;
  animation: marquee-scroll var(--marquee-duration, 30s) linear infinite;
  animation-play-state: var(--marquee-state, running);
}

.marquee--reverse .marquee__list {
  animation-direction: reverse;
}

.marquee--pause-hover:hover .marquee__list {
  animation-play-state: paused;
}

@keyframes marquee-scroll {
  to {
    transform: translateX(-100%);
  }
}

/* ---- Item ---- */

.marquee__item {
  display: flex;
  align-items: center;
  gap: var(--spacing-4, 16px);
  padding: var(--spacing-3, 12px) var(--spacing-4, 16px);
  flex-shrink: 0;
  white-space: nowrap;
}

/* ---- Logos mode ----
   Tira de marcas de cliente. Los logos llegan con proporciones y pesos opticos
   dispares, asi que la unica medida que se puede igualar por CSS es la ALTURA;
   lo demas es correccion caso por caso.

   --marquee-logo-scale existe justo para eso. La correccion optica que vivia en
   prod la hacia un embed con selectores por nombre de archivo
   (img[src*="toyota"] { transform: scale(.76) }): se rompia al renombrar el
   asset y era invisible desde el panel. Como variable por item, la pone quien
   edita y sobrevive al asset.

   OJO en Webflow: el panel del Designer no declara custom properties y rechaza
   el atributo style, asi que ahi la correccion va como combo class por marca
   con la altura ya multiplicada (.ds-marquee__logo.ds-logo--toyota
   { height: 2.66rem }), que gana por especificidad. La variable sigue siendo el
   contrato para React y CLI. */

.marquee__logo {
  display: block;
  /* La correccion optica multiplica la ALTURA, no un transform: scale().
     Un transform no cambia la caja: el logo corregido al alza se sale de su
     item y se monta sobre el siguiente, y el hueco corregido a la baja queda
     de mas. Se veia sobre todo al reiniciar el ciclo, porque ahi coinciden el
     ultimo item de una lista y el primero de la siguiente. Con height la caja
     crece o encoge con el logo y el ritmo del carril vuelve a ser real. */
  height: calc(var(--marquee-logo-height, 3rem) * var(--marquee-logo-scale, 1));
  width: auto;
  /* Webflow sirve img { max-width: 100% } de fabrica: sin esto, un wordmark
     ancho se comprime en vez de respetar su altura. */
  max-width: none;
  object-fit: contain;
}

/* El espaciado sigue el modelo del marquee de Osmo: el padding del item va a UN
   SOLO lado. Con padding en los dos, el hueco entre logos es el DOBLE del valor
   declarado y el primer logo entra despegado del borde de la seccion; con un
   solo lado, el valor declarado ES el hueco y la tira arranca a ras.
   El default de .marquee__item (12/16px) sirve para texto, no para marcas:
   dos logos separados por 32px se leen como un logo compuesto.

   Va como modificador del ITEM y no como modo del carril (.marquee--logos ...)
   por el canal de Webflow: el panel del Designer no declara selectores
   descendentes, asi que un modo en el contenedor no se puede reproducir ahi y
   la tira quedaria sin espaciado en el canvas. Como combo class del item, si.

   Sin separador entre logos: se probo un punto de acento y en una tira de
   marcas ajenas mete un tercer color que compite con cada logo. El ritmo lo
   marca el hueco. */
.marquee__item--logo {
  padding-block: var(--spacing-4);
  padding-inline: 0 var(--marquee-logo-gap, var(--spacing-10));
}

/* Insignia: mas alta que un logo de cliente porque no es una marca, es un sello
   —G2, Meta, HubSpot— y lleva texto dentro que a 3.5rem no se lee.

   Va como modificador y no como --marquee-logo-height en el consumidor porque
   el panel de Webflow no declara custom properties: alli una variable no se
   puede pasar, un combo class si. */
.marquee__logo--badge {
  height: var(--marquee-badge-height, 5rem);
}

/* ---- Separator (optional decorative element between items) ---- */

.marquee__separator {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--muted-foreground);
}

.marquee__separator svg {
  width: 1em;
  height: 1em;
}

/* ---- Draggable mode (GSAP) ---- */

/* En modo draggable el desplazamiento lo pone GSAP sobre __collection. La
   animacion CSS de __list seguiria corriendo sobre el MISMO eje y sumaria un
   segundo movimiento: la tira avanza al doble y el wrap de GSAP deja de cuadrar
   con el ancho real. Se apaga aqui, no en el behavior, porque es pintura. */
.marquee--draggable .marquee__list {
  animation: none;
}

.marquee__collection {
  display: flex;
  align-items: stretch;
  flex: none;
  will-change: transform;
  cursor: grab;
}

.marquee__collection:active {
  cursor: grabbing;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .marquee__list {
    animation-play-state: paused;
  }
}

/* ---- Controles prev/next ----
   Van FUERA de .marquee, no dentro: .marquee es el carril de recorte
   (overflow: hidden) y meterlos ahi los ataria al alto de la tira. Como fila
   propia debajo, el recorte sigue siendo solo del carril.

   El loop es infinito, asi que no hay estado deshabilitado: no existe un primer
   ni un ultimo item que alcanzar. Un carrusel acotado si lo necesitaria. */

.marquee__controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  margin-block-start: var(--spacing-6);
}

.marquee__control {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: none;
  width: 2.5rem;
  height: 2.5rem;
  padding: 0;
  border: var(--stroke-thin) solid var(--border);
  border-radius: var(--radius-full);
  background-color: var(--card);
  color: var(--foreground);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition:
    background-color var(--duration-200) var(--easing-out),
    border-color var(--duration-200) var(--easing-out);
}

.marquee__control:hover {
  background-color: var(--accent);
  border-color: var(--border-focus);
}

.marquee__control:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
}

.marquee__control svg {
  width: 1em;
  height: 1em;
}

@media (prefers-reduced-motion: reduce) {
  .marquee__control {
    transition-duration: 0ms;
  }
}

